import csv

def load(path):
    rows = []
    with open(path, encoding="utf-8", newline="") as f:
        for ts, src, dst, proto, port, size in csv.reader(f):
            rows.append({"ts": int(ts), "src": src, "dst": dst, "proto": proto, "port": int(port), "size": int(size)})
    return rows

limit = int(input())
rows = load("capture.csv")
ports = {}
for r in rows:
    if r["proto"] == "TCP":
        ports.setdefault(r["src"], set()).add(r["port"])
found = [ip for ip in sorted(ports) if len(ports[ip]) >= limit]
if found:
    for ip in found:
        print("SCAN SUSPECT " + ip + " ports=" + str(len(ports[ip])))
else:
    print("no scan detected")
